const foldedPt = Object.fromEntries(Object.entries(operationsPt).map(([key, value]) => [key.toLowerCase(), value]));

export function opsText(value: string): string {
  return i18n.resolvedLanguage === 'pt' ? operationsPt[value] ?? foldedPt[value.toLowerCase()] ?? value : value;
}

export function opsLocale(): string {
  return i18n.resolvedLanguage === 'pt' ? 'pt-MZ' : 'en-GB';
}

// The CTM API currently returns English date labels. Parse only its known format.
export function opsDate(value: string): string {
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const match = value.match(/^(\d{1,2}) ([A-Z][a-z]{2}) (\d{4})$/);
  const month = match ? months.indexOf(match[2]) : -1;
  const iso = match && month >= 0 ? `${match[3]}-${String(month + 1).padStart(2, '0')}-${match[1].padStart(2, '0')}` : value;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(iso)) return value;
  const date = new Date(`${iso}T12:00:00`);
  if (!Number.isFinite(date.getTime())) return value;
  return new Intl.DateTimeFormat(opsLocale(), { day: 'numeric', month: 'short', year: 'numeric' }).format(date);
}
